import { z } from 'zod'
import { DeviceSelectionTraceV1Schema } from './art-director-v1.js'
import { StudioSeriesSchema } from './series.js'

export const JOB_SCHEMA_VERSION_V2 = 2 as const
export const VISUAL_CONTRACT_VERSION_V1 = 1 as const
export const Sha256V1Schema = z.string().regex(/^[a-f0-9]{64}$/)
export const IdentifierV1Schema = z.string().regex(/^[a-z0-9][a-z0-9_-]{1,95}$/i)
export const SeriesV2Schema = StudioSeriesSchema
export type SeriesV2 = z.infer<typeof SeriesV2Schema>
export const SourceModeV2Schema = z.enum(['extract', 'solo', 'short_native'])
export type SourceModeV2 = z.infer<typeof SourceModeV2Schema>
export const VideoPlatformV1Schema = z.enum(['youtube_shorts', 'linkedin', 'tiktok', 'instagram_reels'])
export type VideoPlatformV1 = z.infer<typeof VideoPlatformV1Schema>
export const TreatmentLaneV1Schema = z.enum(['restrained', 'premium', 'experimental'])
export type TreatmentLaneV1 = z.infer<typeof TreatmentLaneV1Schema>

export const StageNameV2Schema = z.enum(['brief','script','recording_brief','ingest','normalize','transcript','source_analysis','candidates','claims','visual_plan','assets','styleframes','animatic','treatment','render','qa','package'])
export type StageNameV2 = z.infer<typeof StageNameV2Schema>
export const ApprovalGateV2Schema = z.enum(['angle','evidence','visual_plan','storyboard','animatic','treatment','final','package'])
export type ApprovalGateV2 = z.infer<typeof ApprovalGateV2Schema>

export const NormalizedPointV1Schema = z.object({ x: z.number().min(0).max(1), y: z.number().min(0).max(1), z: z.number().optional() }).strict()
export const NormalizedRectV1Schema = z.object({ x: z.number().min(0).max(1), y: z.number().min(0).max(1), width: z.number().positive().max(1), height: z.number().positive().max(1) }).strict().superRefine((v,c) => {
  if (v.x + v.width > 1.000001) c.addIssue({ code:'custom', path:['width'], message:'rectangle exceeds normalized width' })
  if (v.y + v.height > 1.000001) c.addIssue({ code:'custom', path:['height'], message:'rectangle exceeds normalized height' })
})
export type NormalizedRectV1 = z.infer<typeof NormalizedRectV1Schema>

export const SourceSyncV1Schema = z.object({ strategy:z.enum(['embedded_timecode','audio_waveform','manual_offset','already_mixed']), offset_ms:z.number().int(), confidence:z.number().min(0).max(1).optional(), reference_source_id:IdentifierV1Schema.optional() }).strict()
export const ParticipantReferenceV1Schema = z.discriminatedUnion('kind', [
  z.object({ kind:z.literal('krish_profile'), profile_id:IdentifierV1Schema, version_hash:Sha256V1Schema, display_name:z.literal('Krish') }).strict(),
  z.object({ kind:z.literal('job_local'), label:z.string().trim().min(1).max(80), consent_ref:z.string().trim().min(1) }).strict(),
])
export type ParticipantReferenceV1 = z.infer<typeof ParticipantReferenceV1Schema>

const participantReferenceKey = (participant: ParticipantReferenceV1): string => participant.kind === 'krish_profile'
  ? `krish_profile:${participant.profile_id.toLowerCase()}`
  : `job_local:${participant.consent_ref.toLowerCase()}`

export const MediaSourceV1Schema = z.object({
  source_id:IdentifierV1Schema, kind:z.enum(['video','audio','screen_recording']), role:z.enum(['primary_camera','secondary_camera','guest_camera','mixed_program','isolated_audio','screen_recording','reference']), ref:z.string().min(1), content_hash:Sha256V1Schema.optional(), rights:z.enum(['owned','permissioned','commentary_exception','unverified']).default('unverified'), consent_ref:z.string().min(1).optional(), participant:ParticipantReferenceV1Schema.optional(), participants:z.array(ParticipantReferenceV1Schema).max(32).optional(), attribution:z.string().min(1).optional(),rights_rationale:z.string().min(20).optional(),editorial_purpose:z.string().min(20).optional(),sync:SourceSyncV1Schema, include_in_edit:z.boolean().default(true),
}).strict().superRefine((v,c) => {
  if (['primary_camera','secondary_camera','guest_camera','mixed_program'].includes(v.role) && v.kind !== 'video') c.addIssue({ code:'custom', path:['kind'], message:`${v.role} must be video` })
  if (v.role === 'isolated_audio' && v.kind !== 'audio') c.addIssue({ code:'custom', path:['kind'], message:'isolated_audio must be audio' })
  if (v.role === 'screen_recording' && v.kind !== 'screen_recording') c.addIssue({ code:'custom', path:['kind'], message:'screen_recording role requires screen_recording kind' })
  if (v.rights === 'commentary_exception' && (!v.attribution || !v.rights_rationale || !v.editorial_purpose)) c.addIssue({ code:'custom', path:['rights'], message:'commentary-exception sources require attribution, a rights rationale, and a recorded editorial purpose' })
  if (v.participant && v.participants?.length) c.addIssue({ code:'custom', path:['participants'], message:'use canonical participants[] or the legacy singular participant, never both' })
  const roster=v.participants?.length?v.participants:(v.participant?[v.participant]:[])
  if (new Set(roster.map(participantReferenceKey)).size!==roster.length) c.addIssue({ code:'custom', path:['participants'], message:'participant roster contains duplicate declarations' })
  if (v.include_in_edit&&v.role==='guest_camera'&&!roster.some(participant=>participant.kind==='job_local')) c.addIssue({ code:'custom', path:['participants'], message:'included guest_camera sources require a consented job-local participant roster' })
  if (v.include_in_edit&&v.role==='mixed_program'&&!roster.length) c.addIssue({ code:'custom', path:['participants'], message:'included mixed_program sources require a participant roster' })
})
export type MediaSourceV1 = z.infer<typeof MediaSourceV1Schema>
export function mediaSourceParticipantRoster(source: Pick<MediaSourceV1, 'participant' | 'participants'>): ParticipantReferenceV1[] {
  return source.participants?.length ? source.participants : source.participant ? [source.participant] : []
}
export const SourceSidecarV1Schema = z.object({
  sidecar_id:IdentifierV1Schema,
  source_id:IdentifierV1Schema,
  kind:z.enum(['captions','edit_decisions']),
  format:z.enum(['srt','vtt','edl','fcpxml']),
  ref:z.string().min(1),
  content_hash:Sha256V1Schema,
}).strict().superRefine((value,context)=>{
  if (value.kind==='captions'&&!['srt','vtt'].includes(value.format)) context.addIssue({ code:'custom', path:['format'], message:'caption sidecars must use SRT or VTT' })
  if (value.kind==='edit_decisions'&&!['edl','fcpxml'].includes(value.format)) context.addIssue({ code:'custom', path:['format'], message:'edit-decision sidecars must use EDL or FCPXML' })
})
export type SourceSidecarV1 = z.infer<typeof SourceSidecarV1Schema>

export const SourceBundleV1Schema = z.object({ schema_version:z.literal(1), bundle_id:IdentifierV1Schema, primary_source_id:IdentifierV1Schema, sources:z.array(MediaSourceV1Schema).min(1).max(32), sidecars:z.array(SourceSidecarV1Schema).max(32).optional(), intake_provenance:z.object({candidate_id:z.string().regex(/^intake_[a-f0-9]{24}$/),candidate_hash:Sha256V1Schema,review_id:z.string().uuid(),review_hash:Sha256V1Schema,inbox_fingerprint:Sha256V1Schema,discovery_event_hash:Sha256V1Schema,media_hashes:z.array(Sha256V1Schema).min(1).max(32),sidecar_hashes:z.array(Sha256V1Schema).max(32),verified_at:z.string().datetime()}).strict().optional() }).strict().superRefine((v,c) => {
  const ids=v.sources.map(x=>x.source_id)
  if (new Set(ids).size !== ids.length) c.addIssue({ code:'custom', path:['sources'], message:'source IDs must be unique' })
  const primary=v.sources.find(x=>x.source_id===v.primary_source_id)
  if (!primary) c.addIssue({ code:'custom', path:['primary_source_id'], message:'primary source must exist' })
  else if (primary.kind==='audio') c.addIssue({ code:'custom', path:['primary_source_id'], message:'primary source must contain video' })
  v.sources.forEach((x,i)=>{ if(x.sync.reference_source_id && !ids.includes(x.sync.reference_source_id)) c.addIssue({ code:'custom', path:['sources',i,'sync','reference_source_id'], message:'sync reference must exist' }) })
  const sidecarIds=(v.sidecars??[]).map(sidecar=>sidecar.sidecar_id)
  if (new Set(sidecarIds).size!==sidecarIds.length) c.addIssue({ code:'custom', path:['sidecars'], message:'sidecar IDs must be unique' })
  ;(v.sidecars??[]).forEach((sidecar,index)=>{ if(!ids.includes(sidecar.source_id)) c.addIssue({ code:'custom', path:['sidecars',index,'source_id'], message:'sidecar source must exist' }) })
  if (v.intake_provenance) {
    const sourceHashes=v.sources.map(source=>source.content_hash)
    if (sourceHashes.some(hash=>!hash)) c.addIssue({ code:'custom', path:['sources'], message:'Drive intake source bundles require a content hash for every source' })
    const declared=[...v.intake_provenance.media_hashes].sort()
    const actual=sourceHashes.filter((hash):hash is string=>Boolean(hash)).sort()
    if (JSON.stringify(declared)!==JSON.stringify(actual)) c.addIssue({ code:'custom', path:['intake_provenance','media_hashes'], message:'Drive intake provenance media hashes must exactly match source content hashes' })
    const declaredSidecars=[...v.intake_provenance.sidecar_hashes].sort()
    const actualSidecars=(v.sidecars??[]).map(sidecar=>sidecar.content_hash).sort()
    if (JSON.stringify(declaredSidecars)!==JSON.stringify(actualSidecars)) c.addIssue({ code:'custom', path:['intake_provenance','sidecar_hashes'], message:'Drive intake provenance sidecar hashes must exactly match typed sidecars' })
  }
})
export type SourceBundleV1 = z.infer<typeof SourceBundleV1Schema>

export const StageStateV2Schema = z.object({ status:z.enum(['pending','running','complete','blocked','invalidated','skipped']), artifact_hash:Sha256V1Schema.optional(), artifact_path:z.string().min(1).optional(), updated_at:z.string().min(1), reason:z.string().min(1).optional() }).strict()
export const ApprovalV2Schema = z.object({ gate:ApprovalGateV2Schema, decision:z.enum(['approved','rejected','override']), artifact_hash:Sha256V1Schema, reason:z.string().min(1).optional(), actor:z.enum(['krish','codex','system']).default('krish'), confirmation_ref:z.string().min(12).max(800).optional(), occurred_at:z.string().min(1) }).strict().superRefine((v,c)=>{ if(v.decision==='override'&&!v.reason?.trim()) c.addIssue({code:'custom',path:['reason'],message:'override requires a reason'}) })
export const JobManifestV2Schema = z.object({
  schema_version:z.literal(JOB_SCHEMA_VERSION_V2), job_id:IdentifierV1Schema, created_at:z.string().min(1), updated_at:z.string().min(1), series:SeriesV2Schema, mode:SourceModeV2Schema, purpose:z.enum(['production','calibration']).default('production'), presenter_name:z.literal('Krish').optional(), source_bundle:SourceBundleV1Schema.optional(), target_platforms:z.array(VideoPlatformV1Schema).min(1).max(4).refine(v=>new Set(v).size===v.length,{message:'target platforms must be unique'}), treatment_lane:TreatmentLaneV1Schema, identity_profile:z.object({profile_id:IdentifierV1Schema,version_hash:Sha256V1Schema,display_name:z.literal('Krish')}).strict().optional(), consent_refs:z.array(z.string().min(1)).default([]), config_hash:Sha256V1Schema, skill_hashes:z.record(z.string(),Sha256V1Schema), pinned_inputs:z.object({config_path:z.string().min(1),skill_paths:z.record(z.string(),z.string().min(1)),technique_registry_path:z.string().min(1).optional(),technique_registry_hash:Sha256V1Schema.optional()}).strict(), stages:z.record(StageNameV2Schema,StageStateV2Schema), approvals:z.array(ApprovalV2Schema), review_decision_hashes:z.array(Sha256V1Schema).default([]),
}).strict().superRefine((v,c)=>{if(v.mode!=='short_native'&&!v.source_bundle)c.addIssue({code:'custom',path:['source_bundle'],message:'extract and solo jobs require a source bundle at creation'})})
export type JobManifestV2 = z.infer<typeof JobManifestV2Schema>
export const StudioEventV2Schema = z.object({ schema_version:z.literal(2), event_id:z.string().uuid(), job_id:IdentifierV1Schema, type:z.enum(['job_created','source_bundle_attached','stage_started','stage_completed','stage_invalidated','stage_blocked','approval_recorded','feedback_recorded','rule_promoted','capability_downgraded','asset_approved','identity_enrolled','identity_revoked','magic_edit_intent_received','magic_edit_candidate_created','magic_edit_activated','review_decision_recorded','review_recovery_recorded']), occurred_at:z.string().min(1), payload:z.record(z.string(),z.unknown()) }).strict()
export type StudioEventV2 = z.infer<typeof StudioEventV2Schema>

export const FeedbackScopeV2Schema=z.object({level:z.enum(['global','series','mode','treatment','platform','job']),key:z.string().min(1)}).strict()
export const FeedbackEventV2Schema=z.object({schema_version:z.literal(2),feedback_id:z.string().uuid(),job_id:IdentifierV1Schema,artifact_id:z.string().min(1),artifact_kind:z.enum(['script','candidate','caption','visual_plan','asset','styleframe','animatic','treatment','render','copy','external_final','approval']),stage:StageNameV2Schema,action:z.enum(['accept','reject','revise','praise']),origin:z.enum(['user','codex','system']).default('user'),evidence_class:z.literal('taste'),before_hash:Sha256V1Schema,after_hash:Sha256V1Schema.optional(),delta_features:z.array(z.object({feature:z.string().min(1),before:z.unknown().optional(),after:z.unknown().optional()}).strict()),user_note:z.string().min(1).optional(),inferred_rationale:z.string().min(1),confidence:z.number().min(0).max(1),scope:FeedbackScopeV2Schema,confirmation:z.enum(['pending','confirmed','corrected','observation_only']),occurred_at:z.string().min(1),exact_external_final:z.boolean().default(false)}).strict().superRefine((v,c)=>{if(v.exact_external_final&&v.artifact_kind!=='external_final')c.addIssue({code:'custom',path:['artifact_kind'],message:'exact external final flag requires external_final kind'});if(v.origin!=='user'&&v.confirmation!=='observation_only')c.addIssue({code:'custom',path:['confirmation'],message:'non-user feedback can only be an observation'})})
export type FeedbackEventV2=z.infer<typeof FeedbackEventV2Schema>
export const FeedbackConfirmationV2Schema = z.object({
  schema_version: z.literal(2),
  confirmation_id: z.string().uuid(),
  feedback_id: z.string().uuid(),
  job_id: IdentifierV1Schema,
  event_hash: Sha256V1Schema,
  confirmation: z.enum(['confirmed', 'corrected']),
  confirmed_rationale: z.string().min(1),
  confirmation_ref: z.string().min(12).max(800),
  confirmed_at: z.string().min(1),
}).strict().superRefine((value, context) => {
  const legacyPrefix = `codex-user-confirmation:feedback:${value.event_hash}:`
  const portablePrefix = /^studio-user-confirmation:(?:control_center|codex_desktop|codex_cli|codex_cloud|claude_desktop|claude_code|claude_ai|chatgpt|other_mcp):feedback:[a-f0-9]{64}:/
  const portableMatch = value.confirmation_ref.match(portablePrefix)?.[0]
  const portableHash = portableMatch?.split(':')[3]
  const legacyValid = value.confirmation_ref.startsWith(legacyPrefix) && Boolean(value.confirmation_ref.slice(legacyPrefix.length).trim())
  const portableValid = portableHash === value.event_hash && Boolean(portableMatch && value.confirmation_ref.slice(portableMatch.length).trim())
  if (!legacyValid && !portableValid) {
    context.addIssue({ code: 'custom', path: ['confirmation_ref'], message: 'feedback confirmation requires an event-bound user receipt from a supported studio client' })
  }
})
export type FeedbackConfirmationV2 = z.infer<typeof FeedbackConfirmationV2Schema>

export const TimedRectKeyframeV1Schema = z.object({ at_ms:z.number().int().nonnegative(), bounds:NormalizedRectV1Schema, confidence:z.number().min(0).max(1) }).strict()
export const HandRectKeyframeV1Schema = TimedRectKeyframeV1Schema.extend({ hand:z.enum(['left','right','unknown']) }).strict()
export const AnalyzedSourceV1Schema = z.object({ source_id:IdentifierV1Schema, source_hash:Sha256V1Schema, duration_ms:z.number().int().positive(), width:z.number().int().positive(), height:z.number().int().positive(), fps:z.number().positive(), audio_hz:z.number().int().positive().nullable(), canonical_offset_ms:z.number().int() }).strict()
export const ShotBoundaryV1Schema = z.object({ shot_id:IdentifierV1Schema, source_id:IdentifierV1Schema, start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), transition:z.enum(['source_start','hard_cut','dissolve','fade','camera_stop','unknown']), confidence:z.number().min(0).max(1) }).strict().refine(v=>v.end_ms>v.start_ms,{message:'shot must end after it starts'})
export const SubjectTrackV1Schema = z.object({ track_id:IdentifierV1Schema, source_id:IdentifierV1Schema, role:z.enum(['krish','guest','unknown']), profile_id:IdentifierV1Schema.optional(), profile_version_hash:Sha256V1Schema.optional(), start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), face_keyframes:z.array(TimedRectKeyframeV1Schema), body_keyframes:z.array(TimedRectKeyframeV1Schema), hand_keyframes:z.array(HandRectKeyframeV1Schema), detection_confidence:z.number().min(0).max(1) }).strict().superRefine((v,c)=>{
  if(v.end_ms<=v.start_ms)c.addIssue({code:'custom',path:['end_ms'],message:'subject track must end after start'})
  if(v.role==='krish'&&(!v.profile_id||!v.profile_version_hash))c.addIssue({code:'custom',path:['profile_id'],message:'Krish track requires enrolled profile provenance'})
  if(v.role!=='krish'&&(v.profile_id||v.profile_version_hash))c.addIssue({code:'custom',path:['profile_id'],message:'guest identities must remain job-local'})
  ;(['face_keyframes','body_keyframes','hand_keyframes'] as const).forEach(k=>v[k].forEach((x,i)=>{if(x.at_ms<v.start_ms||x.at_ms>v.end_ms)c.addIssue({code:'custom',path:[k,i,'at_ms'],message:'keyframe outside subject track'})}))
})
export const ActiveSpeakerIntervalV1Schema = z.object({ interval_id:IdentifierV1Schema, source_id:IdentifierV1Schema, track_id:IdentifierV1Schema.optional(), speaker_label:z.string().min(1).max(80), start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), overlap:z.boolean().default(false), confidence:z.number().min(0).max(1) }).strict().refine(v=>v.end_ms>v.start_ms,{message:'speaker interval must end after start'})
export const GestureTargetV1Schema = z.discriminatedUnion('kind',[z.object({kind:z.literal('point'),point:NormalizedPointV1Schema}).strict(),z.object({kind:z.literal('track'),target_id:IdentifierV1Schema}).strict(),z.object({kind:z.literal('region'),target_id:IdentifierV1Schema}).strict(),z.object({kind:z.literal('direction'),direction:z.enum(['left','right','up','down','camera'])}).strict()])
export const GestureIntervalV1Schema = z.object({ gesture_id:IdentifierV1Schema, track_id:IdentifierV1Schema, start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), hand:z.enum(['left','right','both','unknown']), kind:z.enum(['point','present','draw','hold','count','open_palm','emphasis','other']), direction:z.enum(['left','right','up','down','camera','unknown']).optional(), target:GestureTargetV1Schema.optional(), confidence:z.number().min(0).max(1) }).strict().refine(v=>v.end_ms>v.start_ms,{message:'gesture must end after start'})
export const GazeIntervalV1Schema = z.object({ gaze_id:IdentifierV1Schema, track_id:IdentifierV1Schema, start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), direction:z.enum(['camera','left','right','up','down','other_subject','object','unknown']), target_id:IdentifierV1Schema.optional(), confidence:z.number().min(0).max(1) }).strict().refine(v=>v.end_ms>v.start_ms,{message:'gaze must end after start'})
export const TimedRegionV1Schema = z.object({ region_id:IdentifierV1Schema, source_id:IdentifierV1Schema, start_ms:z.number().int().nonnegative(), end_ms:z.number().int().positive(), bounds:NormalizedRectV1Schema, reason:z.string().min(8), confidence:z.number().min(0).max(1) }).strict().refine(v=>v.end_ms>v.start_ms,{message:'region must end after start'})
export const AnalysisSidecarV1Schema = z.object({ sidecar_id:IdentifierV1Schema, kind:z.enum(['mask','depth','landmarks','optical_flow','speaker_embeddings']), source_id:IdentifierV1Schema, path:z.string().min(1), sha256:Sha256V1Schema, start_ms:z.number().int().nonnegative().optional(), end_ms:z.number().int().positive().optional() }).strict()
export const SourceQualityIssueV1Schema = z.object({ issue_id:IdentifierV1Schema, source_id:IdentifierV1Schema, kind:z.enum(['blur','noise','underexposure','overexposure','occlusion','dropped_frames','audio_drift','tracking_loss','identity_ambiguity','speaker_ambiguity','other']), severity:z.enum(['info','warn','block']), detail:z.string().min(8), start_ms:z.number().int().nonnegative().optional(), end_ms:z.number().int().positive().optional() }).strict()
const unique=(xs:string[])=>new Set(xs).size===xs.length
export const SourceVisualAnalysisV1Schema = z.object({ schema_version:z.literal(1), analysis_id:IdentifierV1Schema, job_id:IdentifierV1Schema, source_bundle_hash:Sha256V1Schema, coordinate_space:z.literal('normalized_0_1'), timebase:z.literal('source_local_ms'), generated_at:z.string().min(1), capabilities:z.object({tier:z.union([z.literal(1),z.literal(2),z.literal(3)]),analyzers:z.record(z.string(),z.string().min(1)),unavailable:z.array(z.string().min(1)).default([]),fallbacks:z.array(z.string().min(1)).default([])}).strict(), sources:z.array(AnalyzedSourceV1Schema).min(1).max(32), shots:z.array(ShotBoundaryV1Schema), subjects:z.array(SubjectTrackV1Schema), active_speakers:z.array(ActiveSpeakerIntervalV1Schema), gestures:z.array(GestureIntervalV1Schema), gaze:z.array(GazeIntervalV1Schema), negative_space:z.array(TimedRegionV1Schema), protected_regions:z.array(TimedRegionV1Schema), sidecars:z.array(AnalysisSidecarV1Schema), quality_issues:z.array(SourceQualityIssueV1Schema) }).strict().superRefine((v,c)=>{
  const sources=new Map(v.sources.map(x=>[x.source_id,x])); const tracks=new Map(v.subjects.map(x=>[x.track_id,x]))
  if(!unique(v.sources.map(x=>x.source_id)))c.addIssue({code:'custom',path:['sources'],message:'source IDs must be unique'})
  if(!unique(v.shots.map(x=>x.shot_id)))c.addIssue({code:'custom',path:['shots'],message:'shot IDs must be unique'})
  if(!unique(v.subjects.map(x=>x.track_id)))c.addIssue({code:'custom',path:['subjects'],message:'track IDs must be unique'})
  ;([['shots',v.shots],['active_speakers',v.active_speakers],['negative_space',v.negative_space],['protected_regions',v.protected_regions]] as const).forEach(([k,xs])=>xs.forEach((x,i)=>{const s=sources.get(x.source_id);if(!s)c.addIssue({code:'custom',path:[k,i,'source_id'],message:'unknown source'});else if(x.end_ms>s.duration_ms)c.addIssue({code:'custom',path:[k,i,'end_ms'],message:'item exceeds source duration'})}))
  v.subjects.forEach((x,i)=>{const s=sources.get(x.source_id);if(!s)c.addIssue({code:'custom',path:['subjects',i,'source_id'],message:'unknown source'});else if(x.end_ms>s.duration_ms)c.addIssue({code:'custom',path:['subjects',i,'end_ms'],message:'track exceeds source duration'})})
  v.active_speakers.forEach((x,i)=>{if(x.track_id&&!tracks.has(x.track_id))c.addIssue({code:'custom',path:['active_speakers',i,'track_id'],message:'unknown subject track'})})
  v.gestures.forEach((x,i)=>{const t=tracks.get(x.track_id);if(!t)c.addIssue({code:'custom',path:['gestures',i,'track_id'],message:'unknown subject track'});else if(x.start_ms<t.start_ms||x.end_ms>t.end_ms)c.addIssue({code:'custom',path:['gestures',i],message:'gesture outside track'})})
  v.gaze.forEach((x,i)=>{const t=tracks.get(x.track_id);if(!t)c.addIssue({code:'custom',path:['gaze',i,'track_id'],message:'unknown subject track'});else if(x.start_ms<t.start_ms||x.end_ms>t.end_ms)c.addIssue({code:'custom',path:['gaze',i],message:'gaze outside track'})})
  ;([...v.sidecars,...v.quality_issues]).forEach((x,i)=>{if(!sources.has(x.source_id))c.addIssue({code:'custom',path:['sidecars_or_quality',i,'source_id'],message:'unknown source'})})
})
export type SourceVisualAnalysisV1 = z.infer<typeof SourceVisualAnalysisV1Schema>

