export const RenderManifestV2Schema=z.object({schema_version:z.literal(2),manifest_id:IdentifierV1Schema,job_id:IdentifierV1Schema,candidate_id:IdentifierV1Schema,candidate_hash:Sha256V1Schema,visual_plan_artifact_hash:Sha256V1Schema,storyboard_artifact_hash:Sha256V1Schema.optional(),series:SeriesV2Schema,treatment_id:IdentifierV1Schema,treatment_lane:TreatmentLaneV1Schema,target_platform:VideoPlatformV1Schema,output:PlatformOutputV1Schema,duration_ms:z.number().int().positive(),sources:z.array(RenderSourceV2Schema).min(1).max(32),shot_directives:z.array(ShotDirectiveV1Schema).min(1),assets:z.array(VisualAssetV1Schema),generated_shots:z.array(GeneratedShotV1Schema),captions:z.array(CaptionCueV2Schema),caption_provenance:z.object({transcript_hash:Sha256V1Schema,verified:z.literal(true),exact_word_fidelity:z.literal(true),source_token_count:z.number().int().nonnegative(),caption_token_count:z.number().int().nonnegative()}).strict(),audio_plan:AudioPlanV1Schema,branding:z.object({mode:z.enum(['series','none']),theme_id:IdentifierV1Schema.optional(),theme_version:z.number().int().positive().optional(),theme_hash:Sha256V1Schema.optional(),wordmark_hashes:z.array(Sha256V1Schema).default([])}).strict(),disclosures:z.array(DisclosureDecisionV1Schema),fixed_seed:z.string().min(16)}).strict().superRefine((v,c)=>{
 if(v.output.platform!==v.target_platform)c.addIssue({code:'custom',path:['output','platform'],message:'output platform must match render target'})
 if(v.duration_ms>v.output.maximum_duration_ms)c.addIssue({code:'custom',path:['duration_ms'],message:'render exceeds platform duration'})
 const sources=v.sources.map(x=>x.source_id)
 if(!unique(sources))c.addIssue({code:'custom',path:['sources'],message:'source IDs must be unique'})
 const sourceSet=new Set(sources),sourceMap=new Map(v.sources.map(x=>[x.source_id,x]))
 v.shot_directives.forEach((x,i)=>{
   if(!sourceSet.has(x.source_id))c.addIssue({code:'custom',path:['shot_directives',i,'source_id'],message:'unknown render source'})
   if(x.end_ms>v.duration_ms)c.addIssue({code:'custom',path:['shot_directives',i,'end_ms'],message:'shot exceeds duration'})
   if(x.audio_continuity!=='direct')c.addIssue({code:'custom',path:['shot_directives',i,'audio_continuity'],message:'non-direct shot audio continuity is not implemented; use direct'})
   const source=sourceMap.get(x.source_id)
   if(source?.kind==='audio')c.addIssue({code:'custom',path:['shot_directives',i,'source_id'],message:'shot source must contain video'})
   if(source&&x.source_end_ms>source.duration_ms)c.addIssue({code:'custom',path:['shot_directives',i,'source_end_ms'],message:'shot exceeds source duration'})
   x.layers.forEach((layer,layerIndex)=>{const layerSource=layer.kind==='source'&&layer.target_id?sourceMap.get(layer.target_id):undefined;if(layerSource?.kind==='audio')c.addIssue({code:'custom',path:['shot_directives',i,'layers',layerIndex,'target_id'],message:'visual source layers cannot reference an audio-only source'})})
 })
 v.audio_plan.dialogue_source_ids.forEach((sourceId,i)=>{const source=sourceMap.get(sourceId);if(!source)c.addIssue({code:'custom',path:['audio_plan','dialogue_source_ids',i],message:'unknown dialogue source'});else if(!source.audio_hz)c.addIssue({code:'custom',path:['audio_plan','dialogue_source_ids',i],message:'dialogue source has no audio'})})
 const sortedDialogue=v.audio_plan.dialogue_edits.map((edit,index)=>({edit,index})).sort((left,right)=>left.edit.output_start_ms-right.edit.output_start_ms||left.edit.output_end_ms-right.edit.output_end_ms)
 let dialogueCoveredUntil=0
 sortedDialogue.forEach(({edit,index})=>{
   const source=sourceMap.get(edit.source_id)
   if(!source)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'source_id'],message:'unknown dialogue source'})
   else{if(!source.audio_hz)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'source_id'],message:'dialogue source has no audio'});if(edit.source_end_ms>source.duration_ms)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'source_end_ms'],message:'dialogue edit exceeds source duration'})}
   if(edit.output_end_ms>v.duration_ms)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'output_end_ms'],message:'dialogue edit exceeds render duration'})
   if(edit.output_start_ms<dialogueCoveredUntil)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'output_start_ms'],message:`dialogue timeline overlaps from ${edit.output_start_ms} ms to ${dialogueCoveredUntil} ms`})
   else if(edit.output_start_ms>dialogueCoveredUntil)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits',index,'output_start_ms'],message:`dialogue timeline has a gap from ${dialogueCoveredUntil} ms to ${edit.output_start_ms} ms`})
   dialogueCoveredUntil=Math.max(dialogueCoveredUntil,edit.output_end_ms)
 })
 if(dialogueCoveredUntil<v.duration_ms)c.addIssue({code:'custom',path:['audio_plan','dialogue_edits'],message:`dialogue timeline ends at ${dialogueCoveredUntil} ms before render duration ${v.duration_ms} ms`})
 v.captions.forEach((x,i)=>{if(x.end_ms>v.duration_ms)c.addIssue({code:'custom',path:['captions',i,'end_ms'],message:'caption exceeds duration'})})
 const assetHashes=new Set(v.assets.map(x=>x.sha256));v.generated_shots.forEach((x,i)=>{if(!assetHashes.has(x.output_hash))c.addIssue({code:'custom',path:['generated_shots',i,'output_hash'],message:'generated output missing from exact asset ledger'})})
})
export type RenderManifestV2=z.infer<typeof RenderManifestV2Schema>

