export const StageArtifactV2Schema=StageArtifactV2BaseSchema.superRefine((v,c)=>{const schemas:Partial<Record<StageNameV2,z.ZodType>>={source_analysis:SourceVisualAnalysisV1Schema,visual_plan:VisualNarrativePlanV1Schema,assets:AssetsStagePayloadV2Schema,styleframes:StoryboardReviewPacketV1Schema,animatic:StoryboardReviewPacketV1Schema,treatment:TreatmentStagePayloadV2Schema,render:RenderStagePayloadV2Schema,package:PackageStagePayloadV2Schema};const parsed=schemas[v.stage]?.safeParse(v.payload);if(parsed&&!parsed.success)parsed.error.issues.forEach(i=>c.addIssue({code:'custom',path:['payload',...i.path],message:i.message}));if(parsed?.success&&v.stage==='styleframes'&&(parsed.data as {review_kind?:string}).review_kind!=='styleframes')c.addIssue({code:'custom',path:['payload','review_kind'],message:'styleframes stage requires styleframes packet'});if(parsed?.success&&v.stage==='animatic'&&(parsed.data as {review_kind?:string}).review_kind!=='animatic')c.addIssue({code:'custom',path:['payload','review_kind'],message:'animatic stage requires animatic packet'})})
